mapper.update:
UPDATE itinerary_planning_request
SET status = 'GENERATING', version = version + 1, updated_at = #{now}
WHERE id = #{requestId} AND owner_member_id = #{ownerMemberId}
  AND version = #{expectedVersion} AND status IN ('DRAFT', 'READY', 'FAILED')

UPDATE itinerary_planning_request
SET status = #{status}, version = version + 1, updated_at = #{now}
WHERE id = #{requestId} AND owner_member_id = #{ownerMemberId} AND status = 'GENERATING'

mapper.select:
SELECT id, itinerary_id, owner_member_id, schema_version, start_date, end_date,
       budget_amount, budget_currency, party_size, preferences_json, status, version
FROM itinerary_planning_request WHERE id = #{requestId}

SELECT id, planning_request_id, name, country_code, time_zone, position
FROM itinerary_planning_destination WHERE planning_request_id = #{requestId}
ORDER BY position, id

mapper.update:
UPDATE itinerary_revision_proposal SET status = 'EXPIRED', resolved_at = #{now}
WHERE planning_request_id = #{requestId} AND status = 'READY'
  AND id != #{exceptProposalId}

mapper.select:
SELECT id, proposal_id, member_id, decision_id, decision_type, selected_operations_hash,
       expected_itinerary_version, itinerary_command_id, result_version
FROM itinerary_revision_resolution WHERE decision_id = #{decisionId}

SELECT id, proposal_id, member_id, decision_id, decision_type, selected_operations_hash,
       expected_itinerary_version, itinerary_command_id, result_version
FROM itinerary_revision_resolution WHERE proposal_id = #{proposalId}
